  function localizedDifficulty(o){if(o.difficulty===.76)return s.lang==='ru'?'Легко':s.lang==='en'?'Easy':'Leicht';if(o.difficulty===1.34)return s.lang==='ru'?'Тяжело':s.lang==='en'?'Hard':'Schwer';return s.lang==='ru'?'Нормально':s.lang==='en'?'Normal':'Normal'}
