  function timeWord(unit,n){
    if(s.lang==='en')return unit;
    if(s.lang==='ru'){
      if(unit==='d')return 'д';
      if(unit==='h')return 'ч';
      if(unit==='m')return 'мин';
      return 'с';
    }
    if(unit==='d')return 'T';
    if(unit==='h')return 'h';
    if(unit==='m')return 'min';
    return 's';
  }
  timeLeft=function(ms){let sec=Math.max(0,Math.ceil(ms/1000));let d=Math.floor(sec/86400),h=Math.floor(sec/3600)%24,m=Math.floor(sec/60)%60,sx=sec%60;if(d)return `${d} ${timeWord('d')} ${h} ${timeWord('h')}`;if(h)return `${h} ${timeWord('h')} ${m} ${timeWord('m')}`;if(m)return `${m} ${timeWord('m')}`;return `${sx} ${timeWord('s')}`;};
  longTime=function(ms){let n=Math.max(0,Math.ceil(ms/1000)),d=Math.floor(n/86400),h=Math.floor(n/3600)%24,m=Math.floor(n/60)%60;if(d)return `${d} ${timeWord('d')} ${h} ${timeWord('h')} ${m} ${timeWord('m')}`;if(h)return `${h} ${timeWord('h')} ${m} ${timeWord('m')}`;if(m)return `${m} ${timeWord('m')} ${n%60} ${timeWord('s')}`;return `${n} ${timeWord('s')}`;};
  compact=function(n){if(!Number.isFinite(n))return '–';let a=Math.abs(n);let u=s.lang==='ru'?[[1e15,'квдр.'],[1e12,'трлн'],[1e9,'млрд'],[1e6,'млн'],[1e3,'тыс.']]:s.lang==='en'?[[1e15,'Qd'],[1e12,'T'],[1e9,'B'],[1e6,'M'],[1e3,'k']]:[[1e15,'Brd.'],[1e12,'Bio.'],[1e9,'Mrd.'],[1e6,'Mio.'],[1e3,'k']];if(a<10000)return Number(n).toLocaleString(getLocale());if(a>=1e18)return n.toExponential(1);let [d,label]=u.find(q=>a>=q[0]);return (n/d).toLocaleString(getLocale(),{maximumFractionDigits:1})+' '+label};
