  function injectStyle(){if(document.getElementById('kwars-v15-style'))return;let st=document.createElement('style');st.id='kwars-v15-style';st.textContent="\n#kwLangBar{display:flex;gap:6px;align-items:center;justify-content:flex-end;margin-top:8px;flex-wrap:wrap}\n#kwLangBar .langTitle{font-size:11px;opacity:.7;letter-spacing:.08em;text-transform:uppercase}\n#kwLangBar button{min-width:42px;padding:6px 10px;border-radius:999px;border:1px solid rgba(255,255,255,.18);background:#1c222a;color:#f3f5f8;cursor:pointer;font-weight:700}\n#kwLangBar button.active{background:#3b4e63;border-color:#85b0ff;box-shadow:0 0 0 1px rgba(133,176,255,.25) inset}\n#screen .kw-mission-bg,#screen .kw-fight-bg{position:relative;overflow:hidden;isolation:isolate}\n#screen .kw-mission-bg>* ,#screen .kw-fight-bg>*{position:relative;z-index:1}\n#screen .kw-mission-bg::before,#screen .kw-fight-bg::before{content:\"\";position:absolute;inset:0;z-index:0;background-image:linear-gradient(180deg,rgba(10,12,16,.20),rgba(10,12,16,.78)),var(--kw-mission-bg);background-size:cover;background-position:center;filter:saturate(1.03)}\n#screen .kw-fight-bg::before{background-image:linear-gradient(180deg,rgba(8,10,14,.35),rgba(8,10,14,.88)),var(--kw-mission-bg)}\n#screen .kw-mission-bg img,#screen .kw-fight-bg img{background:rgba(0,0,0,.22);backdrop-filter:blur(1px);border-radius:16px;padding:4px}\n#screen .kw-mission-bg h3,#screen .kw-fight-bg .name{ text-shadow:0 2px 8px rgba(0,0,0,.55)}\n#screen .kw-backdrop-tag{display:inline-flex;align-items:center;gap:8px;margin-top:8px;padding:6px 10px;border-radius:999px;background:rgba(10,12,16,.56);border:1px solid rgba(255,255,255,.12);font-size:12px}\n";document.head.appendChild(st)}
  function injectLangBar(){
    document.documentElement.lang=s.lang||'de'; if(page!=='Mehr')return; let panel=document.querySelector('#screen .panel.scene');if(!panel)return;
    let box=document.createElement('div');box.id='kwLangBar';box.innerHTML=`<span class="langTitle">${missionLabel('Sprache','Language','Язык')}</span>${['de','en','ru'].map(k=>`<button class="${s.lang===k?'active':''}" onclick="setLang('${k}')">${LANG_LABELS[k]}</button>`).join('')}`;panel.appendChild(box);
  }
  function replaceText(text){let rules=KW_REPLACE[s.lang]||[]; for(let [a,b] of rules) text=text.split(a).join(b); return text;}
  function translateNode(root){
    if(!root||s.lang==='de')return;
    let walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT,null);
    let node; while(node=walker.nextNode()){
      let txt=node.nodeValue; if(!txt||!txt.trim())continue; let next=replaceText(txt); if(next!==txt)node.nodeValue=next;
    }
    root.querySelectorAll('[title]').forEach(el=>{let t=el.getAttribute('title'); if(t) el.setAttribute('title',replaceText(t));});
  }
  function applyTranslations(){
    if(s.lang==='de')return;
    ['nav','screen','lvl','res','modal'].forEach(id=>translateNode(document.getElementById(id)));
  }
