  const regex={}; for(const lang of ['en','ru'])regex[lang]=new RegExp('(?<![\\p{L}\\p{N}_])(?:'+[...dict[lang].keys()].sort((a,b)=>b.length-a.length).map(reEscape).join('|')+')(?![\\p{L}\\p{N}_])','gu');
  function loc(v){return s.lang==='de'?v:String(v).replace(regex[s.lang],x=>dict[s.lang].get(x)??x)}
  replaceText=loc;
  const oldName=name;name=function(i){return loc(oldName(i));};
  const uniqueFlavor=[['The dam was approved. By the beaver himself.','Плотину одобрил сам бобр.'],['Three hours streaming. Four seconds of patience.','Три часа стрима. Четыре секунды терпения.'],['Chat calls it content. The washer calls it overtime.','Чат называет это контентом. Стиралка — переработкой.'],['A lifetime subscription. Unfortunately, to a deposit machine.','Пожизненная подписка. Увы, на таромат.'],['Every key a comment. None of the comments helpful.','Каждая клавиша — комментарий. Ни один не полезен.'],['Chat says skill issue. The slippers say time to clock out.','Чат говорит: скилл ишью. Шлёпанцы говорят: пора домой.']];
