  // Translation after any direct modal opening, timer update, and NPC dialogue event.
  function localizeRoot(root){if(!root||s.lang==='de')return;let walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);let n;while(n=walker.nextNode()){let value=n.nodeValue,translated=loc(value);if(value!==translated)n.nodeValue=translated;}for(let e of root.querySelectorAll('[title],[aria-label],[alt]'))for(let a of ['title','aria-label','alt']){let v=e.getAttribute(a);if(v&&loc(v)!==v)e.setAttribute(a,loc(v));}}
  const roots=['screen','nav','modal','lvl','res','npcSubtitle'];
  applyTranslations=function(){for(let id of roots)localizeRoot(document.getElementById(id));};
  const observer=new MutationObserver(records=>{if(s.lang==='de')return;observer.disconnect();for(let id of roots)localizeRoot(document.getElementById(id));observer.observe(document.body,{childList:true,subtree:true,characterData:true});});
  observer.observe(document.body,{childList:true,subtree:true,characterData:true});
  const oldConfirm=window.confirm.bind(window);window.confirm=(v)=>oldConfirm(loc(v));
