  window.kwLocaleDiagnostics=()=>({items:contentNames.length+UNIQUES.length,foes:foeTranslations.length+MEME_FOES.length,bosses:bossTranslations.length,npc:npcTranslations.length,speeches:speechTranslations.length,lookup:dict.en.size});


