  startJourney=function(){if(s.travel||s.shift||battle?.running)return;if(bagFull()){note('Rucksack voll – zuerst Platz schaffen.');render();return}let o=offers[mp];if(!o||!spendEnergy(o.cost))return;let r=activeRide(),duration=effectiveDuration(o),now=Date.now();s.travel={o:{...o,duration,g:Math.round(o.g*(1+r.gold)),x:Math.round(o.x*(1+r.xp)),ride:s.vehicle,rideDrop:r.drop,rideGems:r.gems},start:now,end:now+duration};AudioGame.fx('travel');AudioGame.voice('questStart');note(hubLabel('Unterwegs: ','Travelling: ','В пути: ')+o.name);render()};
  function fleetPrice(i,n=1){let r=KW_RIDES[i];return {gold:(i===0?250:r.costGold)*n,gems:r.costCrystal*n}}
