  function canContract(i,n){if(!validRide(i)||!Number.isSafeInteger(n)||n<1||n>4)return false;let p=fleetPrice(i,n);return s.gold>=p.gold&&s.premium>=p.gems&&!battle?.running}
  function buyRide(i,n=1){initFleetState();if(!canContract(i,n))return;let p=fleetPrice(i,n);s.gold-=p.gold;s.premium-=p.gems;s.fleet.until[i]=Math.max(Date.now(),s.fleet.until[i])+n*CONTRACT_MS;s.vehicle=i;initFleetState();closeItem();AudioGame.fx('cash');note(hubLabel('Fahrzeugvertrag verlängert: ','Vehicle contract extended: ','Договор продлён: ')+rideText(rideStats(i)));render()}
