  function upgradePlan(i){let l=s.fleet.levels[i],r=KW_RIDES[i],f=Math.pow(l+1,1.35),req={scrap:Math.min(200,Math.ceil((3+i*2)*f)),bolts:Math.min(200,Math.ceil((2+i)*f))};req.tape=Math.min(80,Math.ceil((1+i*.5)*f));if(i>=1)req.oil=Math.min(80,Math.ceil(i*f));if(i>=2)req.wire=Math.min(80,Math.ceil((i-1)*f));if(i>=1)req.rubber=Math.min(160,Math.ceil((1+i)*f));if(i>=2)req.electronics=Math.min(160,Math.ceil((i-1)*f));if(i>=3)req.precision=Math.min(100,Math.ceil((i-2)*f));return {req,gold:Math.ceil((300+i*400+Math.max(0,r.costGold)*.08)*Math.pow(l+1,1.55)),gems:Math.ceil((1+i*.6)*Math.pow(l+1,.7)),duration:gmTime('fleet',Math.round((180000+i*90000)*Math.pow(l+1,1.2)))}}
