  function beginRideUpgrade(i){initFleetState();if(!canUpgrade(i))return;let p=upgradePlan(i);if(!consumeMaterials(p.req))return;s.gold-=p.gold;s.premium-=p.gems;let now=Date.now();s.fleet.job={i,start:now,end:now+p.duration,level:s.fleet.levels[i]+1};save();closeItem();AudioGame.fx('upgrade');render()}
