  function fleetBonus(r){return [[hubLabel('Reisezeit','Travel time','Время пути'),r.speed,'−',false],[hubLabel('Cash','Cash','Деньги'),r.gold,'+',false],['XP',r.xp,'+',false],[hubLabel('Itemfund','Item chance','Шанс предмета'),r.drop,'+',true],[hubLabel('Kristallfund','Crystal chance','Шанс кристалла'),r.gems,'+',true]].filter(a=>a[1]).map(([n,v,sign,pp])=>`<div><small>${n}</small><b>${sign}${pp?pctText(v).replace(' %',' '+hubLabel('Pkt.','pp','п.п.')):pctText(v)}</b></div>`).join('')}
  function contractTime(i){let left=s.fleet.until[i]-Date.now();return left>0?longTime(left):hubLabel('Abgelaufen / nicht gemietet','Expired / not rented','Истёк / не арендован')}
  function fleetView(){settleFleet();let i=fleetIndex,r=rideStats(i),tx=r[s.lang]||r.de,owned=s.vehiclesOwned[i],active=s.vehicle===i,j=s.fleet.job;return `<div class="row fleetTop"><small>${hubLabel('Ausbau','Upgrade','Улучшение')} ${s.fleet.levels[i]}</small></div><div class="fleetCard panel grow"><div class="fleetArtSpace"><div class="fleetArt"><img src="${KW_RIDE_ART[i]}" alt="${tx.name}"><span class="fleetTag">${tx.tag}</span><span class="fleetStatus">${active?hubLabel('AKTIV','ACTIVE','АКТИВЕН'):owned?hubLabel('GEMIETET','RENTED','АРЕНДОВАН'):hubLabel('VERFÜGBAR','AVAILABLE','ДОСТУПЕН')}</span></div></div><h3>${tx.name}</h3><small class="fleetDesc">${tx.desc}</small><small id="contractLeft">${contractTime(i)}</small><div class="fleetBonuses">${fleetBonus(r)}</div></div><div class="fleetPicker">${KW_RIDES.map((v,k)=>`<button class="${i===k?'active':''}" onclick="browseRide(${k})" aria-label="${rideText(v)}"><img src="${KW_RIDE_ART[k]}" alt=""><span>${s.vehicle===k?'✓':s.vehiclesOwned[k]?'•':k+1}</span></button>`).join('')}</div><div class="fleetButtons"><button class="primary" onclick="contractDialog(${i})" >${owned?hubLabel('Verlängern','Extend','Продлить'):hubLabel('Mieten','Rent','Аренда')} · 3 ${hubLabel('Tage','days','дня')}</button><button onclick="upgradeDialog(${i})">${hubLabel('Ausbau','Upgrade','Улучшение')}${j?.i===i?' …':' ›'}</button></div>${owned&&!active?`<button onclick="selectRide(${i})">${hubLabel('Fahrzeug wählen','Select vehicle','Выбрать транспорт')}</button>`:''}`}
  function contractDialog(i){if(!validRide(i))return;initFleetState();$('modal').hidden=false;$('modal').innerHTML=`<div class="sheet"><div class="row"><b>${hubLabel('Fahrzeugvertrag','Vehicle contract','Договор аренды')}</b><button onclick="closeItem()">×</button></div><h3>${rideText(rideStats(i))}</h3><p>${hubLabel('Restlaufzeit','Time remaining','Осталось')}: ${contractTime(i)}</p><small>${hubLabel('Neue Tage werden an die Restlaufzeit angehängt. Ausbaustufen bleiben dauerhaft erhalten.','Extra days are added to remaining time. Upgrades are permanent.','Дни добавляются к оставшемуся сроку. Улучшения сохраняются навсегда.')}</small>${[1,2,3,4].map(n=>`<button class="primary" onclick="buyRide(${i},${n})" ${canContract(i,n)?'':'disabled'}>${n*3} ${hubLabel('Tage','days','дн.')} · ${priceText(fleetPrice(i,n))}</button>`).join('')}</div>`}
