  const oldGarage=garageView;garageView=function(){let i=s.vehicle;return oldGarage().replace(/<button onclick="go\('Arena'\)">([^<]*)<\/button>$/,`<div class="hubActions"><button onclick="go('Arena')">$1</button><button class="fleetEntrance" onclick="fleetOpen()">${validRide(i)?`<img src="${KW_RIDE_ART[i]}" alt="">`:''}<span>${hubLabel('Fuhrpark','Motor pool','Автопарк')}</span></button></div>`)};
