  Object.assign(window,{currentRide,rideText,journeyGold,journeyXp,vehicleDropBonus,vehicleGemBonus,buyRide,selectRide,browseRide,fleetOpen,fleetView,fleetTripChip,contractDialog,upgradeDialog,beginRideUpgrade,kwRideDiagnostics:()=>KW_RIDES.map((r,i)=>({i,active:s.vehicle===i,until:s.fleet.until[i],level:s.fleet.levels[i]}))});
